import { Suspense, lazy } from 'react'

import { MethodItemSuspense } from '~/ui/layout/item/ItemCard'
import type { CommonCardProp } from '~/ui/items/common'

import { name } from './name'

const ItemCard = lazy(() => import('./ItemCard'));


export function RatchetMechanism(prop: CommonCardProp) {
  return (
    <Suspense fallback={<MethodItemSuspense id={name} />}>
      <ItemCard {...prop} />
    </Suspense>
  )
}

